class Solution:
    def shortestDistanceAfterQueries(self, n: int, queries: List[List[int]]) -> List[int]:
        dist = list(range(n - 1, -1, -1))
        ans = []
        for u, v in queries:
            dist[v] = min(dist[v], dist[u] + 1)
            for i in range(v - 1, -1, -1):
                dist[i] = min(dist[i], dist[i + 1] + 1)
            ans.append(dist[n - 1])
        return ans

