class Solution {
public:
    vector<int> shortestDistanceAfterQueries(int n, vector<vector<int>>& queries) {
        vector<int> dist(n), ans;
        for (int i = 0; i < n; i++) dist[i] = n - 1 - i;
        for (auto& q : queries) {
            int u = q[0], v = q[1];
            dist[v] = min(dist[v], dist[u] + 1);
            for (int i = v - 1; i >= 0; i--)
                dist[i] = min(dist[i], dist[i + 1] + 1);
            ans.push_back(dist[n - 1]);
        }
        return ans;
    }
};

