from sortedcontainers import SortedList
class Solution:
    def shortestDistanceAfterQueries(self, n: int, queries: List[List[int]]) -> List[int]:
        segs = SortedList()
        saved = 0
        ans = []
        for u, v in queries:
            while True:
                idx = segs.bisect_left((u, -1))
                if idx < len(segs) and segs[idx][0] >= u and segs[idx][1] <= v:
                    saved -= segs[idx][1] - segs[idx][0] - 1
                    segs.pop(idx)
                else:
                    break
            segs.add((u, v)); saved += v - u - 1
            ans.append(n - 1 - saved)
        return ans

