class Solution {
public:
    vector<int> shortestDistanceAfterQueries(int n, vector<vector<int>>& queries) {
        set<pair<int,int>> segs;
        long saved = 0;
        vector<int> ans;
        for (auto& q : queries) {
            int u = q[0], v = q[1];
            auto it = segs.lower_bound({u, -1});
            while (it != segs.end() && it->first >= u && it->second <= v) {
                saved -= it->second - it->first - 1;
                it = segs.erase(it);
            }
            segs.insert({u, v}); saved += v - u - 1;
            ans.push_back(n - 1 - (int)saved);
        }
        return ans;
    }
};

