class Solution {
    public int[] shortestDistanceAfterQueries(int n, int[][] queries) {
        TreeSet<long[]> segs = new TreeSet<>((a, b) -> a[0] != b[0] ? Long.compare(a[0], b[0]) : Long.compare(a[1], b[1]));
        long saved = 0;
        int[] ans = new int[queries.length];
        for (int qi = 0; qi < queries.length; qi++) {
            int u = queries[qi][0], v = queries[qi][1];
            while (true) {
                long[] probe = segs.ceiling(new long[]{u, -1});
                if (probe != null && probe[0] >= u && probe[1] <= v) {
                    saved -= probe[1] - probe[0] - 1;
                    segs.remove(probe);
                } else break;
            }
            segs.add(new long[]{u, v}); saved += v - u - 1;
            ans[qi] = n - 1 - (int) saved;
        }
        return ans;
    }
}

