// JS lacks a built-in ordered set; emulate with a sorted array of segments.
var shortestDistanceAfterQueries = function(n, queries) {
    let segs = []; // sorted by u, kept small due to laminar property
    let saved = 0;
    const ans = [];
    for (const [u, v] of queries) {
        segs = segs.filter(([a, b]) => {
            if (a >= u && b <= v) { saved -= b - a - 1; return false; }
            return true;
        });
        segs.push([u, v]);
        segs.sort((x, y) => x[0] - y[0]);
        saved += v - u - 1;
        ans.push(n - 1 - saved);
    }
    return ans;
};
